1266	            code = check_password_R5(ctx, ctx->encryption.Password, ctx->encryption.PasswordLen, KeyLen);
1267	            break;
1268	        case 6:
1269	            /* Set up the defaults if not already set */
1270	            /* Revision 6 is always 256-bit AES */
1271	            if (KeyLen != 0)
1272	                pdfi_set_warning(ctx, 0, NULL, W_PDF_SPURIOUS_DECRYPT_LEN, "pdfi_initialise_Decryption", NULL);
1273	            KeyLen = 256;
1274	            if (ctx->encryption.StmF == CRYPT_NONE)
1275	                ctx->encryption.StmF = CRYPT_AESV3;
1276	            if (ctx->encryption.StrF == CRYPT_NONE)
1277	                ctx->encryption.StrF = CRYPT_AESV3;
1278	            code = check_password_R6(ctx, ctx->encryption.Password, ctx->encryption.PasswordLen, KeyLen);
1279	            break;
1280	        default:
1281	            emprintf1(ctx->memory, "\n   **** Warning: This file uses an unknown standard security handler revision: %d\n", ctx->encryption.R);
